$raiz = "C:\Users\cotaw\Desktop\aw-marcenaria"

$arquivos = @{
    "src\components\sections\Processo.jsx" = ""
    "src\app\(site)\page.jsx" = ""
    "src\components\Footer.jsx" = ""
    "src\app\(site)\sobre\page.jsx" = ""
    "src\app\(site)\contato\page.jsx" = ""
    "src\app\(site)\depoimentos\page.jsx" = ""
    "src\app\(site)\portfolio\page.jsx" = ""
    "src\app\(site)\processo\page.jsx" = ""
}

foreach ($rel in $arquivos.Keys) {
    $destino = Join-Path $raiz $rel
    $pastaDestino = Split-Path $destino -Parent
    New-Item -ItemType Directory -Force -Path $pastaDestino | Out-Null
    $bytes = [System.Convert]::FromBase64String($arquivos[$rel])
    [System.IO.File]::WriteAllBytes($destino, $bytes)
    Write-Host "OK - $rel"
}

Write-Host ""
Write-Host "Processo, Home, Footer e 5 paginas standalone criados com sucesso."
Write-Host ""
Write-Host "AGORA PATCH CIRURGICO NO HEADER (so a lista de links, sem tocar no resto do arquivo):"

$headerPath = Join-Path $raiz "src\components\Header.jsx"
$conteudoHeader = Get-Content -LiteralPath $headerPath -Raw

$linksAntigos = @"
  { nome: "Sobre", href: "/#sobre" },
  { nome: "Ambientes", href: "/#ambientes" },
  { nome: "Portfolio", href: "/#portfolio" },
  { nome: "Depoimentos", href: "/#depoimentos" },
  { nome: "Blog", href: "/blog", pagina: true },
  { nome: "Contato", href: "/#contato" },
"@

$linksNovos = @"
  { nome: "Sobre", href: "/#sobre" },
  { nome: "Ambientes", href: "/#ambientes" },
  { nome: "Portfolio", href: "/#portfolio" },
  { nome: "Processo", href: "/#processo" },
  { nome: "Depoimentos", href: "/#depoimentos" },
  { nome: "Blog", href: "/blog", pagina: true },
  { nome: "Contato", href: "/#contato" },
"@

if ($conteudoHeader.Contains($linksAntigos)) {
    $conteudoNovo = $conteudoHeader.Replace($linksAntigos, $linksNovos)
    [System.IO.File]::WriteAllText($headerPath, $conteudoNovo)
    Write-Host "OK - Header.jsx atualizado com link Processo (patch cirurgico, resto do arquivo preservado)"
} else {
    Write-Host "AVISO - Nao encontrei o bloco exato de links no Header.jsx atual."
    Write-Host "O arquivo pode ter mudado desde a ultima auditoria. Adicione manualmente esta linha"
    Write-Host 'no array LINKS, entre Portfolio e Depoimentos:'
    Write-Host '  { nome: "Processo", href: "/#processo" },'
}
